`timescale 1ns / 1ps

// Navigation FSM for the stock-trading game.
// Button inputs are one-clock pulses generated by the top-level debouncer.
module game_fsm (
    input        clk,
    input        rst,
    input        btnU,
    input        btnD,
    input        btnL,
    input        btnR,
    input        btnC,
    output reg [3:0]  screen_state,
    output reg [13:0] quantity
);

    localparam TITLE       = 4'd0;
    localparam PORTFOLIO   = 4'd1;
    localparam STOCKS      = 4'd2;
    localparam SPECIFIC    = 4'd3;
    localparam BUY_STOCK   = 4'd4;
    localparam SELL_STOCK  = 4'd5;
    localparam QUANTITY    = 4'd6;
    localparam CONFIRM     = 4'd7;
    localparam GAME_END    = 4'd8;

    localparam RETURN_BUY  = 1'b0;
    localparam RETURN_SELL = 1'b1;

    reg [3:0] next_state;
    reg [13:0] next_quantity;
    reg        quantity_return_state;
    reg        next_quantity_return_state;
    reg [1:0] quantity_cursor;
    reg [1:0] next_quantity_cursor;

    // Menu cursors are intentionally kept separate for each screen.
    reg [1:0] portfolio_cursor;
    reg [1:0] next_portfolio_cursor;
    reg [2:0] stocks_cursor;       // 0..3 stocks, 4 = back to portfolio
    reg [2:0] next_stocks_cursor;
    reg [1:0] specific_cursor;     // 0 buy, 1 sell, 2 portfolio, 3 stocks
    reg [1:0] next_specific_cursor;
    reg [1:0] buy_cursor;          // 0 back, 1 quantity, 2 confirmation
    reg [1:0] next_buy_cursor;
    reg [1:0] sell_cursor;         // 0 back, 1 quantity, 2 confirmation
    reg [1:0] next_sell_cursor;

    always @(*) begin
        next_state = screen_state;
        next_quantity = quantity;
        next_quantity_return_state = quantity_return_state;
        next_quantity_cursor = quantity_cursor;
        next_portfolio_cursor = portfolio_cursor;
        next_stocks_cursor = stocks_cursor;
        next_specific_cursor = specific_cursor;
        next_buy_cursor = buy_cursor;
        next_sell_cursor = sell_cursor;

        case (screen_state)
            TITLE: begin
                if (btnC) begin
                    next_state = PORTFOLIO;
                    next_portfolio_cursor = 0;
                end
            end

            PORTFOLIO: begin
                if (btnR) next_portfolio_cursor = 1;
                if (btnL) next_portfolio_cursor = 0;

                if (btnC && (portfolio_cursor == 1)) begin
                    next_state = STOCKS;
                    next_stocks_cursor = 0;
                end
            end

            STOCKS: begin
                // U/D select one of four stock entries. L selects back.
                if (btnU) begin
                    if (stocks_cursor == 0 || stocks_cursor == 4)
                        next_stocks_cursor = 3;
                    else
                        next_stocks_cursor = stocks_cursor - 1'b1;
                end

                if (btnD) begin
                    if (stocks_cursor == 3)
                        next_stocks_cursor = 4;
                    else
                        next_stocks_cursor = stocks_cursor + 1'b1;
                end

                if (btnL) next_stocks_cursor = 4;
                if (btnR) next_stocks_cursor = 0;

                if (btnC) begin
                    if (stocks_cursor == 4) begin
                        next_state = PORTFOLIO;
                        next_portfolio_cursor = 0;
                    end else begin
                        next_state = SPECIFIC;
                        next_specific_cursor = 0;
                    end
                end
            end

            SPECIFIC: begin
                // Default selection is buy. R selects sell. U selects the
                // portfolio-back option, then R selects the stocks-back option.
                if (btnU) next_specific_cursor = 2;
                if (btnR) begin
                    if (specific_cursor == 0)
                        next_specific_cursor = 1;
                    else if (specific_cursor == 2)
                        next_specific_cursor = 3;
                end
                if (btnL) begin
                    if (specific_cursor == 1)
                        next_specific_cursor = 0;
                    else if (specific_cursor == 3)
                        next_specific_cursor = 2;
                end

                if (btnC) begin
                    case (specific_cursor)
                        0: begin
                            next_state = BUY_STOCK;
                            next_buy_cursor = 0;
                        end
                        1: begin
                            next_state = SELL_STOCK;
                            next_sell_cursor = 0;
                        end
                        2: begin
                            next_state = PORTFOLIO;
                            next_portfolio_cursor = 0;
                        end
                        3: begin
                            next_state = STOCKS;
                        end
                        default: next_state = SPECIFIC;
                    endcase
                end
            end

            BUY_STOCK: begin
                if (btnR && (buy_cursor < 2))
                    next_buy_cursor = buy_cursor + 1'b1;
                if (btnL && (buy_cursor > 0))
                    next_buy_cursor = buy_cursor - 1'b1;

                if (btnC) begin
                    case (buy_cursor)
                        0: begin
                            next_state = SPECIFIC;
                            next_specific_cursor = 0;
                        end
                        1: begin
                            next_state = QUANTITY;
                            next_quantity = 0;
                            next_quantity_return_state = RETURN_BUY;
                            next_quantity_cursor = 0;
                        end
                        2: begin
                            next_state = CONFIRM;
                        end
                        default: next_state = BUY_STOCK;
                    endcase
                end
            end

            SELL_STOCK: begin
                if (btnR && (sell_cursor < 2))
                    next_sell_cursor = sell_cursor + 1'b1;
                if (btnL && (sell_cursor > 0))
                    next_sell_cursor = sell_cursor - 1'b1;

                if (btnC) begin
                    case (sell_cursor)
                        0: begin
                            next_state = SPECIFIC;
                            next_specific_cursor = 1;
                        end
                        1: begin
                            next_state = QUANTITY;
                            next_quantity = 0;
                            next_quantity_return_state = RETURN_SELL;
                            next_quantity_cursor = 0;
                        end
                        2: begin
                            next_state = CONFIRM;
                        end
                        default: next_state = SELL_STOCK;
                    endcase
                end
            end

            QUANTITY: begin
                // L moves ones -> tens -> hundreds -> thousands.
                if (btnL && (quantity_cursor < 3))
                    next_quantity_cursor = quantity_cursor + 1'b1;

                // R moves thousands -> hundreds -> tens -> ones.
                if (btnR && (quantity_cursor > 0))
                    next_quantity_cursor = quantity_cursor - 1'b1;

                // U/D change the currently selected decimal place while the
                // stored quantity remains a 14-bit binary number.
                if (btnU) begin
                    case (quantity_cursor)
                        0: if (quantity <= 14'd9998) next_quantity = quantity + 1;
                        1: if (quantity <= 14'd9989) next_quantity = quantity + 10;
                        2: if (quantity <= 14'd9899) next_quantity = quantity + 100;
                        3: if (quantity <= 14'd8999) next_quantity = quantity + 1000;
                        default: next_quantity = quantity;
                    endcase
                end

                if (btnD) begin
                    case (quantity_cursor)
                        0: if (quantity >= 1)    next_quantity = quantity - 1;
                        1: if (quantity >= 10)   next_quantity = quantity - 10;
                        2: if (quantity >= 100)  next_quantity = quantity - 100;
                        3: if (quantity >= 1000) next_quantity = quantity - 1000;
                        default: next_quantity = quantity;
                    endcase
                end

                if (btnC) begin
                    if (quantity_return_state == RETURN_BUY) begin
                        next_state = BUY_STOCK;
                        next_buy_cursor = 0;
                    end else begin
                        next_state = SELL_STOCK;
                        next_sell_cursor = 0;
                    end
                end
            end

            CONFIRM: begin
                if (btnC) begin
                    next_state = PORTFOLIO;
                    next_portfolio_cursor = 0;
                end
            end

            GAME_END: begin
                // No game-end transition was specified yet.
                next_state = GAME_END;
            end

            default: next_state = TITLE;
        endcase
    end

    always @(posedge clk) begin
        if (rst) begin
            screen_state <= TITLE;
            quantity <= 0;
            quantity_return_state <= RETURN_BUY;
            quantity_cursor <= 0;
            portfolio_cursor <= 0;
            stocks_cursor <= 0;
            specific_cursor <= 0;
            buy_cursor <= 0;
            sell_cursor <= 0;
        end else begin
            screen_state <= next_state;
            quantity <= next_quantity;
            quantity_return_state <= next_quantity_return_state;
            quantity_cursor <= next_quantity_cursor;
            portfolio_cursor <= next_portfolio_cursor;
            stocks_cursor <= next_stocks_cursor;
            specific_cursor <= next_specific_cursor;
            buy_cursor <= next_buy_cursor;
            sell_cursor <= next_sell_cursor;
        end
    end

endmodule
